97	function setAboutHeroSloganSurfaceAlpha(progress: number): void {
98	  const element = getAboutHeroSloganElement();
99	  if (!element) return;
100	  const clampedProgress = Math.max(0, Math.min(1, progress));
101	  const alpha =
102	    ABOUT_HERO_SLOGAN_ALPHA_MIN +
103	    ABOUT_HERO_SLOGAN_ALPHA_SPAN * clampedProgress;
104	  element.style.setProperty(ABOUT_HERO_SLOGAN_ALPHA_PROPERTY, alpha.toFixed(4));
105	}
106	
107	function resetAboutHeroSloganSurfaceAlpha(): void {
108	  const element = getAboutHeroSloganElement();
109	  if (!element) return;
110	  element.style.setProperty(
111	    ABOUT_HERO_SLOGAN_ALPHA_PROPERTY,
112	    String(ABOUT_HERO_SLOGAN_ALPHA_MIN),
113	  );
114	}
