134	    ABOUT_JOURNEY_SURFACE_SEGMENT_SPAN +
135	    ABOUT_JOURNEY_SURFACE_SEGMENT_SPAN * clampedProgress;
136	  setAboutJourneySurfaceAlpha(alpha);
