143	    ABOUT_JOURNEY_SURFACE_SEGMENT_SPAN * 2 +
144	    ABOUT_JOURNEY_SURFACE_SEGMENT_SPAN * clampedProgress;
145	  setAboutJourneySurfaceAlpha(alpha);
