159	function syncSectionTextReveal(
160	  selector: string,
161	  domState: { visible: boolean; timers: number[] },
162	  progress: number,
163	): void {
164	  const shouldShow = progress >= SECTION_TEXT_REVEAL_THRESHOLD;
165	  const shouldHide = !shouldShow && progress < SECTION_TEXT_HIDE_THRESHOLD;
166	  if (!shouldShow && !shouldHide) return;
167	  if (domState.visible === shouldShow) return;
168	  domState.visible = shouldShow;
169	  domState.timers = clearTimers(domState.timers);
170	  const elements = Array.from(document.querySelectorAll<HTMLElement>(selector));
171	  elements.forEach((el, i) => {
172	    const id = window.setTimeout(() => {
173	      el.classList.toggle("is-block-reveal-up", shouldShow);
174	    }, i * SECTION_TEXT_STAGGER_MS);
175	    domState.timers.push(id);
176	  });
177	}
178	
179	function disposeSectionTextReveal(
180	  selector: string,
181	  domState: { visible: boolean; timers: number[] },
182	): void {
183	  domState.timers = clearTimers(domState.timers);
184	  domState.visible = false;
185	  document
186	    .querySelectorAll<HTMLElement>(selector)
187	    .forEach((el) => el.classList.remove("is-block-reveal-up"));
188	}
