198	function syncAboutContactHead(progress: number): void {
199	  const section = document.querySelector<HTMLElement>(ABOUT_CONTACT_SECTION_SELECTOR);
200	  const head = document.querySelector<HTMLElement>(ABOUT_CONTACT_HEAD_SELECTOR);
201	  const actions = document.querySelector<HTMLElement>(ABOUT_CONTACT_ACTIONS_SELECTOR);
202	  if (!section || !head || !actions) return;
203	
204	  const textItems = Array.from(head.querySelectorAll<HTMLElement>(".mask-target"));
205	  const shouldShow = progress >= CONTACT_HEAD_TRANSITION.revealStart;
206	
207	  if (aboutSceneDomState.isContactHeadVisible === shouldShow) return;
208	  aboutSceneDomState.isContactHeadVisible = shouldShow;
209	  aboutSceneDomState.contactHeadTimers = clearTimers(
210	    aboutSceneDomState.contactHeadTimers,
211	  );
212	
213	  if (shouldShow) {
214	    section.dataset.active = "true";
215	    head.dataset.active = "true";
216	    actions.dataset.active = "true";
217	    TextReveal.setVisibleOff(textItems);
218	    textItems.forEach((item, index) => {
219	      const timerId = window.setTimeout(() => {
220	        TextReveal.setVisibleOn(item);
221	      }, index * CONTACT_HEAD_TRANSITION.revealStagger * 1000);
222	      aboutSceneDomState.contactHeadTimers.push(timerId);
223	    });
224	    return;
225	  }
226	
227	  textItems.forEach((item) => {
228	    TextReveal.setVisibleOff(item);
229	  });
230	  section.dataset.active = "false";
231	  head.dataset.active = "false";
232	  actions.dataset.active = "false";
233	}
