235	function disposeAboutContactHead(): void {
236	  const section = document.querySelector<HTMLElement>(ABOUT_CONTACT_SECTION_SELECTOR);
237	  const head = document.querySelector<HTMLElement>(ABOUT_CONTACT_HEAD_SELECTOR);
238	  const actions = document.querySelector<HTMLElement>(ABOUT_CONTACT_ACTIONS_SELECTOR);
239	  if (!section || !head || !actions) return;
240	
241	  aboutSceneDomState.isContactHeadVisible = false;
242	  aboutSceneDomState.contactHeadTimers = clearTimers(
243	    aboutSceneDomState.contactHeadTimers,
244	  );
245	  section.dataset.active = "false";
246	  head.dataset.active = "false";
247	  actions.dataset.active = "false";
248	
249	  const textItems = Array.from(head.querySelectorAll<HTMLElement>(".mask-target"));
250	  textItems.forEach((item) => TextReveal.setVisibleOff(item));
251	}
